<template>
  <div class="public-site">
    <header class="public-nav">
      <router-link to="/" class="public-brand"><BrandLockup/><span>让每一次相遇，都有归处</span></router-link>
      <nav aria-label="网站导航">
        <router-link to="/adopt">寻找伙伴</router-link><router-link to="/news">平台公告</router-link><router-link to="/guide">参与指南</router-link>
        <router-link v-if="workbench" to="/dashboard">我的工作台</router-link><router-link v-else to="/login">登录</router-link><router-link class="join-link" to="/register">加入宠链</router-link>
      </nav>
    </header>

    <main class="public-main">
      <section v-if="mode==='home'" class="home-hero" aria-labelledby="home-title">
        <img class="hero-image" src="/assets/petlink-home-hero-v2.webp" alt="在温暖晨光中得到照护的猫和狗" width="1536" height="1024" loading="eager" decoding="async" fetchpriority="high"/>
        <div class="hero-shade" aria-hidden="true"></div>
        <div class="hero-copy">
          <p class="hero-kicker"><span></span>实时协作中的生命救助网络</p>
          <h1 id="home-title">让每一次<br><em>被发现</em>，<br>都有抵达家的路径。</h1>
          <p class="hero-intro">宠链连接线索提供者、救援人员与领养家庭，让善意不止停留在看见，而是抵达长久的照护。</p>
          <div class="hero-actions"><router-link class="solid-link" to="/adopt">遇见新伙伴 <span>↗</span></router-link><a class="text-link" :href="memberUrl('clue')">发布救助线索 <span>→</span></a></div>
          <p class="hero-proof">线索、审核、救助、建档、领养、回访，在一个平台完整衔接</p>
        </div>
        <div class="hero-story"><span>PetLink Complete Care</span><b>救助不是终点，<br>被好好陪伴才是。</b><router-link to="/guide">了解我们如何协作 →</router-link></div>
        <div class="hero-scroll" aria-hidden="true"><i></i>向下探索</div>
      </section>

      <div v-if="error" class="public-error" role="alert"><span>{{error}}</span><button type="button" @click="load">重新加载</button></div>

      <section v-if="mode==='home'" class="impact-strip" aria-label="平台公开数据">
        <article><strong>{{homeAnimalTotal}}</strong><span>位伙伴开放领养</span></article><article><strong>{{homeNoticeTotal}}</strong><span>条公开动态持续更新</span></article><article><strong>6</strong><span>个环节形成照护闭环</span></article><article><strong>2 × 3</strong><span>双端连接三类角色</span></article>
      </section>

      <section v-if="mode==='home'" class="journey-section">
        <div class="section-heading journey-heading"><div><p class="overline">A COMPLETE PATH TO HOME</p><h2>一次求助，如何走到一个家</h2></div><p>每一次状态变化都被记录，每一个角色都知道下一步该做什么。</p></div>
        <ol class="journey-track"><li v-for="(step,index) in journeySteps" :key="step.title"><span>0{{index+1}}</span><div><b>{{step.title}}</b><small>{{step.description}}</small></div></li></ol>
      </section>

      <template v-if="['home','adopt'].includes(mode)">
        <div class="section-heading"><div><p class="overline">MEET YOUR NEW COMPANION</p><h2>等待一个家的它们</h2></div><router-link v-if="mode==='home'" class="section-link" to="/adopt">查看全部伙伴 →</router-link><label v-else class="public-select"><span class="sr-only">动物种类</span><select v-model="species" aria-label="动物种类" @change="page=1;load()"><option value="">全部动物</option><option value="CAT">猫</option><option value="DOG">狗</option><option value="OTHER">其他</option></select></label></div>
        <div class="pet-grid" :class="{'is-loading':loading}"><router-link v-for="a in animals" :key="a.id" :to="'/adopt/'+a.id" class="pet-card"><div class="pet-photo-wrap"><AuthImage :src="a.coverImageUrl" :alt="a.name" fallback="/assets/pudding-cat-card-v2.webp" width="720" height="520"/><span class="pet-status">正在寻找新家</span></div><div class="pet-content"><h3>{{a.name}}</h3><p>{{displayText(a.species)}} · {{displayText(a.sex)}} · {{age(a.estimatedAgeMonths)}}</p><p class="pet-health">{{a.healthCondition}}</p><span class="pet-more">认识一下 <i>→</i></span></div></router-link></div>
        <div v-if="!loading&&!error&&!animals.length" class="public-empty">伙伴们还在准备中，请稍后再来看看</div>
        <nav v-if="mode==='adopt'&&total>12" class="public-pager" aria-label="动物列表分页"><button type="button" :disabled="page<=1" @click="goPage(page-1)">上一页</button><span>第 {{page}} / {{pageCount}} 页 · 共 {{total}} 位伙伴</span><button type="button" :disabled="page>=pageCount" @click="goPage(page+1)">下一页</button></nav>
      </template>

      <section v-if="mode==='home'" class="action-bento" aria-label="参与宠链">
        <router-link v-for="(card,index) in companionCards" :key="card.to" :to="card.to" class="action-card" :class="'action-card--'+(index+1)"><img :src="card.image" :alt="card.title" width="720" height="520" loading="lazy" decoding="async"/><div class="action-card-shade"></div><div class="action-card-copy"><span>{{card.eyebrow}}</span><h3>{{card.title}}</h3><p>{{card.description}}</p><b>{{card.action}} →</b></div></router-link>
      </section>

      <section v-if="mode==='animal'&&detail" class="animal-profile"><div class="animal-gallery"><AuthImage v-for="im in detail.images" :key="im.id" :src="im.url" :alt="detail.name"/></div><div><p class="overline">认识你的未来伙伴</p><h1>{{detail.name}}</h1><p>{{displayText(detail.species)}} · {{displayText(detail.sex)}} · {{age(detail.estimatedAgeMonths)}}</p><p class="intro">{{detail.healthCondition}}</p><p>毛色：{{detail.color||'暂未记录'}}</p><a class="solid-link" :href="memberUrl('apply',{animalId:detail.id})">申请领养</a><p class="muted">在公众服务端登录后填写申请，由工作人员审核。</p><h2>健康与照护</h2><div v-for="h in health" :key="h.id" class="health-note"><p>{{h.content}}</p><small>{{date(h.createdAt)}}</small></div><p v-if="!health.length" class="muted">暂无公开健康记录</p><router-link to="/adopt">← 返回动物列表</router-link></div></section>

      <template v-if="['home','news'].includes(mode)"><div class="section-heading notice-heading"><div><p class="overline">STAY CLOSE, ACT TOGETHER</p><h2>宠链公告</h2></div><router-link v-if="mode==='home'" class="section-link" to="/news">全部公告 →</router-link></div><div class="notice-grid" :class="{'is-loading':loading}"><router-link v-for="(n,index) in notices" :key="n.id" :to="'/news/'+n.id" class="public-notice"><span class="notice-index">0{{index+1}}</span><small>{{date(n.publishedAt)}}</small><h3>{{n.title}}</h3><span class="notice-more">阅读全文 →</span></router-link></div><div v-if="!loading&&!error&&!notices.length" class="public-empty">暂无最新公告</div><nav v-if="mode==='news'&&total>12" class="public-pager" aria-label="公告列表分页"><button type="button" :disabled="page<=1" @click="goPage(page-1)">上一页</button><span>第 {{page}} / {{pageCount}} 页 · 共 {{total}} 条公告</span><button type="button" :disabled="page>=pageCount" @click="goPage(page+1)">下一页</button></nav></template>

      <article v-if="mode==='notice'&&detail" class="public-article"><router-link to="/news">← 返回公告</router-link><h1>{{detail.title}}</h1><p class="muted">{{date(detail.publishedAt)}}</p><div class="article-body">{{detail.content}}</div></article>

      <section v-if="mode==='guide'" class="participation"><p class="overline">把善意变成行动</p><h2>每一步，都有人与你同行</h2><div class="steps"><article><b>01 / 发现与记录</b><h3>让需要帮助的它被看见</h3><p>先确保自身安全，不贸然追赶或接触动物。记录地点、发现时间和现场照片，留下可联系的信息。</p><a :href="memberUrl('clue')">发布救助线索 →</a></article><article id="rescue"><b>02 / 专业救助</b><h3>把照护交给合适的人</h3><p>工作人员审核线索后，由救助人员接取、记录处理过程并建立动物档案。可在“我的线索”查看进展。</p><a :href="memberUrl('clue')">查看我的线索 →</a></article><article><b>03 / 领养与陪伴</b><h3>准备好一份长久的承诺</h3><p>了解动物健康与性格，认真填写家庭和居住情况。领养后定期分享近况，让关心它的人放心。</p><router-link to="/adopt">寻找领养伙伴 →</router-link></article></div></section>
